Item.method_code:
const {
	getState,
	rows,
	commandFactory,
	relatedItemType,
	polySources
} = options;

const { grid } = getState();
const selectedRows = grid.selectedRows;
const commandAlias = target['command_alias@keyed_name'];
const itemTypeMetadata = ArasModules.metadata.itemType;
const isPolymorphic = itemTypeMetadata.isPolymorphic(relatedItemType?.id);
const getItemType = (item) => {
	if (isPolymorphic) {
		const itemTypeId = item.itemtype;
		const itemTypeName = itemTypeMetadata.getItemTypeName(itemTypeId);
		return polySources[itemTypeName];
	}

	return relatedItemType;
};
const promises = selectedRows.map(async (rowId) => {
	const relatedId = rows.get(rowId, 'related_id');
	const item = rows.get(relatedId);
	const itemNode = window.getRelatedItem(rowId);
	const itemType = getItemType(item);
	const itemTypeName = itemType.name;
	const claimCommand = commandFactory(commandAlias, {
		item,
		itemNode,
		itemType,
		itemTypeName
	});
	try {
		return await claimCommand.execute();
	} catch (error) {
		if (error.code === 'Client.EditOldItemVersionException') {
			const itemId = itemNode.getAttribute('id');
			const itemLatestVersion = await window.aras.getItemLastVersion(
				itemTypeName,
				itemId
			);
			window.replaceRelatedItem({
				itemLatestVersion,
				relationshipId: rowId
			});
		}
		throw error;
	}
});

const result = Promise.allSettled(promises);

return result;
